draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H/2 + 20 * Math.sin(t));
  ctx.lineTo(W, H/2 + 20 * Math.sin(t + Math.PI));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(0, H - 50 - 10 * Math.cos(t));
  ctx.lineTo(W, H - 50 - 10 * Math.cos(t + Math.PI));
  ctx.lineTo(W, H);
  ctx.stroke();
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 20 * Math.cos(t), H/2 + 10 * Math.sin(t));
  ctx.stroke();
  ctx.restore();
}
